function demo(){state=addCompatibilityAliases(defaultState());Object.assign(state.student,{displayName:'Alex Student',firstName:'Alex',lastName:'Student',graduationYear:'2026'});Object.assign(state.aboutMe,{careerGoal:'Software Developer',biography:'I am a Programming student who enjoys turning ideas into useful tools. Through projects at ECTS, I have grown more confident solving problems, learning from feedback, and working with a team.',skills:['Java','HTML','CSS','JavaScript','problem solving'],interests:['Software design','technology','music','collaborative projects']});state.samples.push(...Array.from({length:5},(_,i)=>({id:id('work'),title:['Java Calculator','Responsive Portfolio Site','Inventory Tracker','Debugging Journal','Team Project'][i],description:'A project that helped me practice planning, building, testing, and explaining my work.',date:'2025',skills:['Programming','problem solving'],classOrProject:'Programming',file:null,link:'',reflection:''})));state.accomplishments.accomplishments=[{...achievement(),title:'Completed a five-project programming portfolio'}];state.accomplishments.awards=[{...achievement(),title:'Programming lab recognition'}];state.recommendations.push({id:id('recommendation'),title:'Recommendation letter',recommenderName:'',recommenderRole:'',description:'',file:null},{id:id('recommendation'),title:'Recommendation letter',recommenderName:'',recommenderRole:'',description:'',file:null});state.supportingAcademics.postSecondaryPlan.plans='Explore a software development program and continue building projects.';state.supportingAcademics.growthReflection={id:id('reflection'),title:'ECTS growth',type:'ECTS Growth',date:'2026',content:'ECTS helped me become more persistent when solving problems.',relatedExperience:''};state.cew.forEach(item=>{item.selected=['Career goal','Work samples'];item.description='My work and reflections show how I am preparing for a future in technology.'});save(true);startApp();toast('Demo portfolio loaded. Explore and edit anything.')}
function ensurePortableShape(portfolio){
	portfolio.supportingAcademics=portfolio.supportingAcademics||{};
	portfolio.supportingAcademics.documents=portfolio.supportingAcademics.documents||{};
	portfolio.careerSafe=portfolio.careerSafe||{};
	if(!Array.isArray(portfolio.careerSafe.entries))portfolio.careerSafe.entries=Object.keys(portfolio.careerSafe).filter(key=>/^careerSafe\d+$/.test(key)).map((key,index)=>{const item=portfolio.careerSafe[key];return {id:id('career-safe'),category:String(index+1),selectedOption:item.selectedOption||'',certificate:item.certificate||null,completionDate:item.completionDate||'',notes:item.notes||''}});
	return portfolio;
}
function academicDocument(key,title){return state.supportingAcademics.documents[key]||(state.supportingAcademics.documents[key]={id:id('academic'),title,fileName:'',fileType:'',fileData:null,uploadedAt:null})}
function academicUpload(key,title){const item=academicDocument(key,title);return `<section class="section-card"><div class="repeater-header"><div><h2>${title}</h2><p>Upload the completed assignment as a PDF from your past work.</p></div><span class="requirement-status ${item.fileName?'done':''}">${item.fileName?'Attached':'PDF required'}</span></div>${fileUpload('',item.fileName?'Replace PDF':'Upload PDF','supportingAcademics.documents.'+key)}</section>`}
function careerSafeView(){const choices=['Teamwork','Interview Skills Certification','Time Management','Cybersecurity','Materials Management','Critical Thinking','Human Resource Management','Communication Skills','Written Communication','Workplace Financial Management','Personal Financial Management'];const entries=state.careerSafe.entries;return heading('07 · CareerSafe','CareerSafe certifications','Add every certification you have completed. You can add multiple entries in the same area.')+entries.map((item,index)=>`<section class="section-card"><div class="repeater-header"><div><p class="section-kicker">CareerSafe evidence ${index+1}</p><h2>Certification details</h2></div>${index>3?`<button class="remove-button" data-remove-safe="${index}">Remove</button>`:''}</div><div class="field-grid"><label class="field-label">Area or category<select data-safe-category="${index}"><option value="">Choose an area</option>${['1','2','3','4'].map(category=>`<option value="${category}" ${item.category===category?'selected':''}>CareerSafe ${category}</option>`).join('')}</select></label><label class="field-label">Certification<select data-safe-entry="${index}"><option value="">Choose a certification</option>${choices.map(choice=>`<option ${item.selectedOption===choice?'selected':''}>${choice}</option>`).join('')}</select></label><label class="field-label">Completion date<input data-safe-date="${index}" value="${esc(item.completionDate||'')}" placeholder="Month, year"></label></div>${fileUpload('',item.certificate?.fileName?'Replace certificate':'Upload certificate','careerSafe.entries.'+index+'.certificate')}<label class="field-label">Notes<textarea data-safe-notes="${index}" placeholder="Optional context about this certification.">${esc(item.notes||'')}</textarea></label></section>`).join('')+'<button class="add-button" data-add="careerSafe">+ Add another CareerSafe entry</button>'}
function academicsView(){const a=state.supportingAcademics;return heading('08 · Look ahead','Supporting academics','Keep completed academic assignments here as PDFs so you can return to them later.')+academicUpload('postSecondary','Post-secondary plan')+academicUpload('growth','Co-op / SkillsUSA / ECTS growth reflection')+academicUpload('reflection1','ATD / field trip reflection 1')+academicUpload('reflection2','ATD / field trip reflection 2')+academicUpload('employment','Standard application for employment')+academicUpload('employers','Potential employers')+academicUpload('education','Post-secondary education opportunities')+academicUpload('home','Home school reflection (optional)')+`<section class="section-card"><h2>Checkoffs</h2><p>Editable sign-off fields for your portfolio review.</p><div class="field-grid"><label class="field-label">Instructional assistant name<input data-bind="academics.iaName" value="${esc(a.instructionalAssistant?.name||'')}"></label><label class="field-label">Date<input data-bind="academics.iaDate" value="${esc(a.instructionalAssistant?.date||'')}"></label><label class="field-label">Instructor name<input data-bind="academics.instructorName" value="${esc(a.instructor?.name||'')}"></label><label class="field-label">Date<input data-bind="academics.instructorDate" value="${esc(a.instructor?.date||'')}"></label></div></section>`}
function addPortableBindings(){const originalBindEditor=bindEditor;bindEditor=function(){originalBindEditor();document.querySelectorAll('[data-file]').forEach(el=>el.onchange=()=>portableFileHandler(el));document.querySelectorAll('[data-safe-category]').forEach(el=>el.onchange=()=>{state.careerSafe.entries[+el.dataset.safeCategory].category=el.value;save(true)});document.querySelectorAll('[data-safe-entry]').forEach(el=>el.onchange=()=>{state.careerSafe.entries[+el.dataset.safeEntry].selectedOption=el.value;save(true);render()});document.querySelectorAll('[data-safe-date]').forEach(el=>el.oninput=()=>{state.careerSafe.entries[+el.dataset.safeDate].completionDate=el.value;save(true)});document.querySelectorAll('[data-safe-notes]').forEach(el=>el.oninput=()=>{state.careerSafe.entries[+el.dataset.safeNotes].notes=el.value;save(true)})};const originalAddItem=addItem;addItem=function(kind){if(kind==='careerSafe'){state.careerSafe.entries.push({id:id('career-safe'),category:'',selectedOption:'',certificate:null,completionDate:'',notes:''});save(true);render();return}originalAddItem(kind)};document.addEventListener('click',event=>{const remove=event.target.closest('[data-remove-safe]');if(remove){state.careerSafe.entries.splice(+remove.dataset.removeSafe,1);save(true);render()}})}
function portableFileHandler(el){const file=el.files[0];if(!file)return;if(file.type!=='application/pdf'&&el.dataset.file.startsWith('supportingAcademics')){toast('Supporting academic assignments must be PDF files.');return}const reader=new FileReader();reader.onload=()=>{const path=el.dataset.file.split('.');let target=state;path.slice(0,-1).forEach(part=>{if(!target[part])target[part]={};target=target[part]});const key=path.at(-1);const metadata={fileName:file.name,fileType:file.type,fileData:reader.result,uploadedAt:new Date().toISOString()};if(target[key]&&typeof target[key]==='object'&&'file' in target[key])target[key].file=metadata;else if(target[key]&&typeof target[key]==='object')Object.assign(target[key],metadata);else target[key]=metadata;save(true);render();toast('File attached. It will be included in your compressed backup.');};reader.readAsDataURL(file)}
async function downloadBackup(){const name=`ects-career-portfolio-${(state.student.displayName||'backup').toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;if(window.portfolioDesktop){if(await window.portfolioDesktop.exportArchive(state,name))toast('Compressed portfolio archive saved. Keep it somewhere private.');return}const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${name}.json`;link.click();URL.revokeObjectURL(link.href);toast('Backup downloaded. Keep it somewhere private.')} 
async function loadBackup(){if(window.portfolioDesktop){try{const portfolio=await window.portfolioDesktop.importArchive();if(!portfolio)return;state=addCompatibilityAliases(ensurePortableShape(portfolio));save(true);startApp();toast('Backup loaded successfully.')}catch{toast('That backup file could not be loaded.')}return}const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=()=>{const file=input.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{state=addCompatibilityAliases(ensurePortableShape(JSON.parse(reader.result)));save(true);startApp();toast('Backup loaded successfully.')}catch{toast('That backup file could not be loaded.')}};reader.readAsText(file)};input.click()}
function reset(){if(confirm('Reset this portfolio? All locally saved information will be removed.')){if(window.portfolioDesktop)window.portfolioDesktop.clearCurrent();else localStorage.removeItem(KEY);state=addCompatibilityAliases(ensurePortableShape(defaultState()));show('landing');toast('Portfolio reset.')}}
state=ensurePortableShape(state);isSectionDone=function(section){if(section==='academics')return ['postSecondary','growth','reflection1','reflection2'].every(key=>academicDocument(key,key).fileName);if(section==='careersafe')return state.careerSafe.entries.slice(0,4).every(item=>item.selectedOption&&item.certificate);return section==='about'?!!(state.student.name&&state.student.goal&&state.student.bio):section==='samples'?state.workSamples.length>=5:section==='credentials'?state.credentials.length>0:section==='accomplishments'?state.accomplishments.accomplishments.length>0:section==='documents'?!!(state.files.cover&&state.files.resume&&state.files.recommendations.filter(Boolean).length>=2):section==='cew'?state.cew.every(item=>item.selected.length&&item.description):false};progress=function(){const checks=[!!(state.student.name&&state.student.goal&&state.student.bio),!!(state.files.cover&&state.files.resume&&state.files.recommendations.filter(Boolean).length>=2),state.workSamples.length>=5,state.credentials.length>0,state.accomplishments.accomplishments.length>0,isSectionDone('careersafe'),isSectionDone('academics'),isSectionDone('cew')];return Math.round(checks.filter(Boolean).length/checks.length*100)};addPortableBindings();
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='start')start();if(action==='demo')demo();if(action==='board-demo')boardDemo();if(action==='home'){e.preventDefault();show('landing');closeMenu()}if(action==='save')save();if(action==='download')downloadBackup();if(action==='load')loadBackup();if(action==='preview')preview();if(action==='close-modal')closePreview();if(action==='print')window.print();if(action==='menu')$('#sidebar').classList.toggle('open');if(action==='requirements'){current='checklist';renderNav();render()};if(action==='reset')reset()});populatePrograms();$('#setup-form').onsubmit=e=>{e.preventDefault();state.student.name=$('#setup-name').value.trim();state.student.year=$('#setup-year').value;state.program.id=$('#setup-program').value;syncProgram();save(true);startApp()};if(state.student.name)startApp();else show('landing');if(window.portfolioDesktop){window.portfolioDesktop.loadCurrent().then(saved=>{if(!saved)return;state=addCompatibilityAliases(ensurePortableShape(saved));if(state.student.name)startApp();else show('landing')}).catch(()=>toast('Unable to load the local portfolio file.'))}
